<!-- This file is generated by AI. -->
<!--
  文本预处理选项卡: 把小说原文转成 WebGAL 脚本, 分四步走。

  与 `packages/webgal-novel-preprocess` 的分工: 那是个**纯逻辑库** (解析 / 预处理 / 序列化),
  这里只做界面与 Monaco 宿主。会话 (`NovelSession`) 存在 `novel/registry.ts` 里, **跨挂载存活** ——
  切走再切回来要停在原来那一步, 而不是回到初始状态。

  因此本组件做两件事: 把 Monaco 包成 `IEditorHost` 交给会话 (挂载时 attach, 卸载时 detach),
  以及订阅会话变化重画界面。会话本身不销毁 (销毁只在关选项卡/关项目时发生)。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->
<script lang="ts">
  import * as monaco from 'monaco-editor';
  import { onDestroy, onMount, untrack } from 'svelte';

  import { diffGutterMarks } from '../editor/diff-gutter';
  import { diffLines } from '../editor/line-diff';
  import { createEditorBlockEmphasisController } from '../novel/block-emphasis';
  import { createEditorHost, createNovelModel, NOVEL_LANGUAGE_ID } from '../novel/monaco';
  import { getOrCreateSession, novelModelUri, releaseSession } from '../novel/registry';
  import { actions, appStore } from '../state/store.svelte';
  import { LANGUAGE_ID } from '../lsp/monaco';
  import AppDialog from './AppDialog.svelte';
  import Button from './Button.svelte';
  import Icon from './Icon.svelte';

  let { id }: { id: string } = $props();

  let host: HTMLDivElement | undefined = $state();
  let editor: monaco.editor.IStandaloneCodeEditor | null = null;
  /*
   * 会话与 model uri 按选项卡 id 取,**只取一次**。
   *
   * 原因: Svelte 的顶层 `const` 只求值一次。因此父级 (`ui/EditorPage.svelte` 的 novel 分支)
   * 的 `{#key activeTab.id}` 是**必须的** —— 不 key 的话, 从"小说 A"切到"小说 B"时组件实例被
   * 复用, 这里仍指向 A 的会话, 编辑器会显示**另一个选项卡的文本**。
   * 会话本身仍存活在 registry 里, `session.attach` 就是为了"换宿主不换会话"。
   *
   * `untrack` 把"只取初值"写成**显式意图** —— 否则编译器会报 `state_referenced_locally`
   * (它无法区分"漏了响应式"与"故意只取一次")。
   */
  const sessionId = untrack(() => id);
  const session = getOrCreateSession(sessionId, placeholderHost());
  /*
   * 会话状态快照。
   *
   * 会话是命令式的 (内部就地改模型), 所以这里靠 `subscribe` 把它拉进响应式;
   * 变量名刻意不叫 `state` —— 那会与 `$state` rune 撞名, 编译器会把 `state` 当成 rune 解析。
   */
  let sessionState = $state(session.getState());
  /** 强制重画的令牌 (会话的模型在内部就地修改, 快照引用可能不变)。 */
  let tick = $state(0);

  const step = $derived(sessionState.step);
  const speakers = $derived(sessionState.speakers);
  const warnings = $derived(sessionState.warnings);
  const diagnostics = $derived(sessionState.diagnostics);

  /** 会话尚未挂载编辑器宿主时的占位实现 (构造需要它, 但真正驱动只在 attach 之后)。 */
  function placeholderHost() {
    return {
      getContent: () => '',
      setContent: () => {},
      setReadOnly: () => {},
      replaceLine: () => {},
      selectLines: () => {},
      setCursorLine: () => {},
      onContentChange: () => () => {},
      onCursorLine: () => () => {},
      onKey: () => () => {},
      focus: () => {},
    };
  }

  onMount(() => {
    if (!host) return;

    const uri = novelModelUri(sessionId);
    const model = createNovelModel(monaco, uri, session.getState().text);
    const instance = monaco.editor.create(host, {
      model,
      theme: appStore.theme === 'dark' ? 'webgal-dark' : 'webgal-light',
      automaticLayout: true,
      minimap: { enabled: false },
      fontFamily: appStore.settings.editorFontFamily,
      fontSize: appStore.settings.editorFontSize,
      wordWrap: appStore.settings.editorWordWrap ? 'on' : 'off',
      // 不设 `scrollBeyondLastLine`: Monaco 默认 true, 与 CodeEditor 保持一致
      renderWhitespace: 'none',
      /*
       * 第 3 步「当前对话段」的箭头画在**字形栏**里 (`block-emphasis` 用 glyphMarginClassName)。
       * Monaco 的 `glyphMargin` 默认是 **false**, 不给这一项箭头就永远不显示。
       */
      glyphMargin: true,
      /*
       * 补全/悬浮等浮层挂到 body 上, 而不是留在编辑器容器里: 容器的 `overflow: hidden` 会把
       * 它们裁掉 (靠边的浮层只显示一半)。`ui/GitDiffEditor.svelte` 也要设这一项。
       */
      fixedOverflowWidgets: true,
    });
    editor = instance;

    // 把 Monaco 包成会话认识的宿主, 并换绑上去 (会话跨挂载存活, 这里只是换宿主)
    const editorHost = createEditorHost(monaco, instance);
    session.attach(editorHost);

    /*
     * 第 3 步的"当前对话段"箭头。
     *
     * 行范围从会话快照读, 而不是自己按光标算: 会话里那份才是权威的 (它还要负责
     * "光标不在对话段上时锁定到向下最近的一段")。快照里的行号是 0 基。
     */
    const emphasis = createEditorBlockEmphasisController({
      editor: instance,
      getRange: () => {
        const current = session.getState();
        // 只有第 3 步画箭头: 其它步骤没有"对话段"这个概念
        if (current.step !== 3 || current.selectedHeadLine < 0) return null;
        return { start: current.selectedHeadLine, end: current.selectedEndLine };
      },
    });

    /*
     * 第 2 / 3 步的差异色块: 与该步开始时的文本比较。
     *
     * * 第 2 步看自动处理的结果又被手动改了什么 (基准是预处理结果);
     * * 第 3 步看说话者分配改了什么 (基准是进入本步时的文本)。
     * 基准由会话给出 (`stepBaseline`), 这里只负责算差异、画色块。
     *
     * 这两步的文字本身是"改过的稿子", 没有差异色块就只能靠肉眼记住原文。
     */
    const diffDecorations = instance.createDecorationsCollection();
    const syncDiff = () => {
      const current = session.getState();
      const model = instance.getModel();
      if (!model || current.stepBaseline === null || (current.step !== 2 && current.step !== 3)) {
        diffDecorations.clear();
        return;
      }
      const marks = diffGutterMarks(diffLines(current.stepBaseline, current.text), model.getLineCount(), (line) =>
        model.getLineMaxColumn(line)
      );
      diffDecorations.set(
        marks.map((mark) => ({
          range: new monaco.Range(mark.lineNumber, 1, mark.lineNumber, mark.endColumn),
          options: { linesDecorationsClassName: mark.className },
        }))
      );
    };

    /*
     * 会话内部就地改模型, 因此每次变化都重新取一次快照、递增令牌, 并重画两种装饰。
     *
     * 装饰跟着会话事件走 (而不是起一个定时器反复重画): 会话在光标换段、内容变化、步骤流转时
     * 都会 `emit` (见 `packages/webgal-novel-preprocess` 的 `session.ts`), 事件驱动既及时
     * 又不会每秒重设好多次装饰 —— 后者会让编辑器看起来在"闪"。
     */
    const unsubscribe = session.subscribe(() => {
      sessionState = session.getState();
      tick += 1;
      emphasis.sync();
      syncDiff();
    });
    emphasis.sync();
    syncDiff();

    /*
     * 状态栏的行/列由这里上报。
     *
     * 预处理卡不是"文档", 但状态栏是全局的: 不上报的话它会一直停在上一个文档的位置。
     * 路径加 `novel:` 前缀与真实文件区分开, 也因此不进 `cursors` 留档表 —— 那个表是给
     * "切走再切回来恢复光标"用的, 预处理卡由会话自己记住位置。
     */
    const cursorSub = instance.onDidChangeCursorPosition((event) => {
      actions.setCursor({ path: `novel:${sessionId}`, line: event.position.lineNumber, column: event.position.column });
    });

    return () => {
      cursorSub.dispose();
      unsubscribe();
      emphasis.dispose();
      instance.dispose();
      // 只解绑宿主, **不销毁会话** —— 切走再切回来要恢复同一步
      releaseSession(sessionId);
      editor = null;
    };
  });

  /*
   * 第 4 步的输出是最终脚本, 用 `webgal` 语言复用语义高亮;
   * 其余步骤用中间格式的语言 (`webgal-novel`)。
   */
  $effect(() => {
    const instance = untrack(() => editor);
    const current = step;
    if (!instance) return;
    const model = instance.getModel();
    if (!model) return;
    const language = current === 4 ? LANGUAGE_ID : NOVEL_LANGUAGE_ID;
    if (model.getLanguageId() !== language) monaco.editor.setModelLanguage(model, language);
  });

  /**
   * 解析诊断与预处理警告同步成 Monaco markers。
   *
   * 两条约束:
   * * **只在第 2 步画**: 行号是相对"预处理结果"的, 到了第 3/4 步文本已经变了, 留着旧标记
   *   会指向错误的位置 (其它步骤一律清空);
   * * **warnings 也要画**: 它们和 diagnostics 一样带行号, 只列在底部列表里的话用户得自己数行。
   */
  $effect(() => {
    const instance = untrack(() => editor);
    const errors = diagnostics;
    const warns = warnings;
    const currentStep = step;
    void tick;
    if (!instance) return;
    const model = instance.getModel();
    if (!model) return;

    if (currentStep !== 2) {
      monaco.editor.setModelMarkers(model, NOVEL_LANGUAGE_ID, []);
      return;
    }

    const marker = (severity: 'error' | 'warning' | 'info', message: string, line: number) => ({
      severity:
        severity === 'error'
          ? monaco.MarkerSeverity.Error
          : severity === 'warning'
            ? monaco.MarkerSeverity.Warning
            : monaco.MarkerSeverity.Info,
      message,
      startLineNumber: line + 1,
      startColumn: 1,
      endLineNumber: line + 1,
      endColumn: model.getLineMaxColumn(Math.min(line + 1, model.getLineCount())),
    });

    monaco.editor.setModelMarkers(model, NOVEL_LANGUAGE_ID, [
      ...errors.map((item) => marker(item.severity, item.message, item.line)),
      // 预处理警告指向它所属的 `;` 注释行
      ...warns.map((item) => marker('warning', item.message, item.line)),
    ]);
  });

  /** 字号/换行等设置热更新 (不重建编辑器)。 */
  $effect(() => {
    const settings = appStore.settings;
    const instance = untrack(() => editor);
    if (!instance) return;
    instance.updateOptions({
      fontFamily: settings.editorFontFamily,
      fontSize: settings.editorFontSize,
      wordWrap: settings.editorWordWrap ? 'on' : 'off',
    });
  });

  /** 光标位置上报 (状态栏显示字数/行数)。 */
  $effect(() => {
    const instance = untrack(() => editor);
    if (!instance) return;
    const sub = instance.onDidChangeModelContent(() => {
      const model = instance.getModel();
      if (!model) return;
      const content = model.getValue();
      actions.setNovelStats({ chars: content.length, lines: model.getLineCount() });
    });
    return () => sub.dispose();
  });

  onDestroy(() => {
    clearTimeout(copiedTimer);
    actions.setNovelStats(null);
    actions.setCursor(null);
  });

  /**
   * 每一步的说明与操作提示。
   *
   * 文案是**操作说明书**: 键位怎么用、前缀什么含义都写在这里, 改写会丢掉"1-9 / A-Z 键位分配"
   * 和"Shift+Alt+F 重新规整空格"这类只有用过才知道的捷径。
   */
  const STEP_INFO: Record<number, { label: string; desc: string; tips: string[] }> = {
    1: {
      label: '输入文本',
      desc: '粘贴小说原文，标点、空格与对话会在下一步自动规整。',
      tips: ['把整篇或整段小说原文粘贴到上方编辑器。', '可以任意分段，空行会被自动清理。'],
    },
    2: {
      label: '格式化与断句',
      desc: '自动处理已完成，可手动微调后再继续。',
      tips: [
        '以 : 开头的一行为旁白；以 %: 开头的一行为待分配对话；无前缀的一行跟随上一句对话的说话者。',
        '对话内容已去掉外层引号，句内引号已规范为双引号。',
        '可直接编辑上方文本；Shift+Alt+F 可重新规整行内空格。',
      ],
    },
    3: {
      label: '设置对话者',
      desc: '进入后自动选中第一段对话，按人物键位分配说话者。',
      tips: [
        '光标移动到某段对话时会自动选中整段（旁白不选）。',
        '按键盘 1-9 或 A-Z 对应人物键位，即可为当前对话段设置说话者；分配后自动跳到下一段。',
        '在下方人物面板填写名称与可选的 figureId；键位为面板上显示的编号。',
        '分配后编辑器内显示为「编号-名称」，导出时自动去掉编号前缀。',
      ],
    },
    4: {
      label: '生成脚本',
      desc: '脚本已生成（只读），复制后粘贴到任意场景即可。',
      tips: ['旁白为 :内容;，对话为 人物名:内容;（可带 -figureId）。', '可手动框选复制，或点击「复制全文」。'],
    },
  };

  const stepInfo = $derived(STEP_INFO[step] ?? STEP_INFO[1]);

  /** 「复制全文」的短暂反馈。 */
  let copied = $state(false);
  let copiedTimer: ReturnType<typeof setTimeout> | undefined;

  async function copyScript(): Promise<void> {
    try {
      await navigator.clipboard.writeText(sessionState.text);
      copied = true;
      clearTimeout(copiedTimer);
      copiedTimer = setTimeout(() => (copied = false), 1500);
    } catch {
      // 剪贴板被拒时不给用户加一层报错: 文本就在眼前, 可以手动框选
    }
  }
</script>

<!--
  布局: **编辑器在上、控制面板在下**。

  "第几步/标题/说明/提示/人物/动作"全在底部面板里, 编辑器独占上方 —— 这也是为什么提示里写的
  是"上方文本"和"下方人物面板"。

  类名沿用 `styles.css` 里的 `.preprocess-panel` / `-step-idx` / `-step-desc` / `-characters*` /
  `-actions` 规则。
-->
<div class="preprocess-tab">
  <div class="preprocess-editor" bind:this={host}></div>

  <div class="preprocess-panel">
    <div class="preprocess-step">
      <span class="preprocess-step-idx">步骤 {step} / 4</span>
      <span class="preprocess-step-label">{stepInfo.label}</span>
      <span class="preprocess-step-desc">{stepInfo.desc}</span>
    </div>

    <ul class="preprocess-tips">
      {#each stepInfo.tips as tip (tip)}
        <li>{tip}</li>
      {/each}
    </ul>

    {#if step === 3}
      <!--
        人物面板: 键位 + 名称 + figureId + 移除, 以及"+ 新增人物"。
        新增直接加一行空人物, 让人名就在行内敲 —— 多一个"请输入名称"的对话框既慢又和旁边那排
        输入框不一致。
      -->
      <div class="preprocess-characters">
        <div class="preprocess-characters-grid">
          {#each speakers as speaker (speaker.key)}
            <div class="preprocess-character">
              <span class="preprocess-character-key">{speaker.key}</span>
              <input
                class="preprocess-character-name"
                value={speaker.name}
                placeholder="人物名称"
                title="人物名称 (约 6 个汉字)"
                oninput={(event) => session.updateSpeaker(speaker.key, { name: event.currentTarget.value })}
              />
              <!--
                figureId 是**可选**的立绘匹配键: 填了导出脚本会带上 `-figureId=`,
                引擎据此选立绘; 不填就得靠人物名匹配。
              -->
              <input
                class="preprocess-character-id"
                value={speaker.figureId ?? ''}
                placeholder="figureId"
                title="figureId (可选, 约 6 个字符)"
                oninput={(event) => session.updateSpeaker(speaker.key, { figureId: event.currentTarget.value })}
              />
              <button
                type="button"
                class="preprocess-character-remove"
                title="移除人物"
                onclick={() => session.removeSpeaker(speaker.key)}
              >
                ×
              </button>
            </div>
          {/each}
          <button type="button" class="preprocess-character-add" onclick={() => session.addSpeaker()}>
            + 新增人物
          </button>
        </div>
      </div>
    {/if}

    <div class="preprocess-actions">
      <Button disabled={!sessionState.canGoBack} onclick={() => session.back()}>上一步</Button>
      <span class="preprocess-actions-spacer"></span>
      <!--
        第 4 步的输出就是最终脚本, 因此把「复制全文」放在"下一步"旁边 ——
        动作栏的顺序是 上一步 / 复制全文 / 下一步。
      -->
      {#if step === 4}
        <!-- 图标与文案一起给出"复制"这个动作; 复制成功后换成对勾, 反馈不必只靠文字 -->
        <Button appearance="primary" icon={copied ? 'Checkmark' : 'Copy'} onclick={() => void copyScript()}>
          {copied ? '已复制' : '复制全文'}
        </Button>
      {:else}
        <!--
          第 4 步是终点: 这里**整个不渲染**「下一步」, 而不是渲染一个永远 disabled 的按钮 ——
          一个点不动的按钮只会让人怀疑是不是还有没做完的步骤。
          `.preprocess-actions-spacer` 仍在上面, 所以「复制全文」的落点不变。
        -->
        <Button appearance="primary" disabled={!sessionState.canGoNext} onclick={() => session.next()}>
          下一步
          <Icon name="ArrowRight" size={14} />
        </Button>
      {/if}
    </div>
  </div>

  <!--
    未分配的对话用**模态框**问一次, 而不是在人物栏里挂一条横幅: 这是一个"要不要继续"的决定,
    横幅容易被当成可以忽略的提示。
  -->
  {#if sessionState.pendingConfirm}
    <AppDialog
      title="存在未分配的对话"
      size="small"
      height={220}
      closeOnBackdrop
      onClose={() => session.resolveUnresolved(false)}
    >
      <p>还有 {sessionState.unresolvedCount} 段对话未设置说话者，是否将其作为旁白处理？</p>
      {#snippet footer()}
        <Button onclick={() => session.resolveUnresolved(false)}>返回继续</Button>
        <Button appearance="primary" onclick={() => session.resolveUnresolved(true)}>作为旁白</Button>
      {/snippet}
    </AppDialog>
  {/if}
</div>
